"""Additional coverage-audit chapter: sixteen original leprosy questions."""
from qbank_authoring import question,ref,finalize
WH=ref('WHO: Leprosy—Diagnosis and Current MDT','https://www.who.int/news-room/fact-sheets/detail/leprosy/')
IN=ref('India NLEP: Revised Classification and Treatment Effective April 2025','https://dghs.mohfw.gov.in/nlep.php')
UK=ref('UKHSA: Memorandum on Leprosy, 2023','https://www.gov.uk/government/publications/leprosy-memorandum/memorandum-on-leprosy-2023')
RE=ref('WHO: Leprosy Reactions and Prevention of Disability','https://iris.who.int/bitstream/handle/10665/332022/9789290227595-eng.pdf')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A patient has a hypopigmented patch with definite sensory loss and a thickened peripheral nerve. Which diagnosis is most concerning?', 'Leprosy',[
 ('Vitiligo as a complete explanation for the sensory and nerve findings','Vitiligo does not usually cause this neuropathic pattern.'),('Pityriasis versicolor as proof of the nerve lesion','Superficial fungal pigmentation does not explain peripheral nerve enlargement.'),('A normal pigmentation variant','Definite sensory loss is pathological.')],
 'Sensory testing distinguishes a neurological skin lesion from pigmentation alone', '**Definite sensory loss in a compatible pale or reddish patch is a cardinal sign.**',['An enlarged nerve with corresponding sensory or motor impairment is another cardinal feature.','A positive slit-skin smear supplies direct bacillary evidence.'], '**Assess skin, nerves, eyes and disability systematically.**',['Use specialist confirmation when the presentation is uncertain.','Early treatment prevents further injury.'],[['Skin','Compatible patch with sensory loss'],['Nerve','Enlargement plus dysfunction'],['Microbiology','Bacilli in slit-skin smear']],[WH],style='clinical_scenario')
q('Which immune pattern most characterizes tuberculoid compared with lepromatous leprosy?', 'Stronger cell-mediated immunity with lower bacillary burden',[
 ('Lower cell-mediated immunity with the highest bacillary burden','That better describes the lepromatous end.'),('No relationship between host immunity and the spectrum','Host response shapes the clinical spectrum.'),('A universal absence of nerve involvement','Nerve injury can be prominent in tuberculoid disease.')],
 'The host response influences both burden and tissue pattern', '**Tuberculoid disease has relatively effective cellular containment.**',['Lepromatous disease has weaker cell-mediated control and more bacilli.','Borderline forms are immunologically unstable.'], '**Do not infer low disability risk from low bacillary burden.**',['Localized nerve inflammation can cause major damage.','Clinical spectrum and operational treatment classification are related but not identical.'],[['Tuberculoid','Higher cellular response, fewer bacilli'],['Lepromatous','Lower cellular response, more bacilli'],['Nerve risk','Important across the spectrum']],[UK,WH])
q('Under India’s revised NLEP classification implemented in 2025, a patient has three skin lesions and definite peripheral nerve involvement. Which operational category applies?', 'Multibacillary',[
 ('Paucibacillary solely because there are fewer than six lesions','The revised Indian classification also uses nerve involvement.'),('No leprosy category can ever be assigned with a negative smear','Clinical disease can be smear negative.'),('A reaction category instead of any treatment classification','Reaction type and operational category are separate decisions.')],
 'Lesion count alone is insufficient in the revised Indian pathway', '**One or more involved nerves places disease in the MB category under the revised NLEP classification.**',['PB requires the appropriate limited-lesion pattern without nerve involvement and with negative smear.','A positive smear also indicates MB disease.'], '**Use the current national protocol explicitly.**',['Older teaching may differ in the nerve criterion.','Record sensory and motor findings carefully.'],[['Lesions','Only three in this case'],['Nerve','Definite involvement'],['Revised NLEP category','MB']],[IN],style='clinical_scenario')
q('A patient has only two visible leprosy lesions but the slit-skin smear is bacillary positive. Which operational category is appropriate?', 'Multibacillary',[
 ('Paucibacillary regardless of smear because lesion count is low','Bacillary positivity changes the classification.'),('No active disease because bacilli never occur in skin','They can be detected by slit-skin smear.'),('A purely allergic disorder','Direct bacillary evidence supports infection.')],
 'A direct organism finding can override a limited visible-lesion count', '**Smear-positive disease is classified as MB.**',['Disease burden is not fully represented by the number of obvious patches.','Assess other skin, nerve and systemic findings.'], '**Select the complete current MDT course.**',['Counsel on adherence and adverse effects.','Continue monitoring for reactions and nerve injury.'],[['Lesion count','Can underestimate burden'],['Smear positive','MB classification'],['Follow-up','Infection treatment and nerve/reaction assessment']],[IN,WH])
q('What is the current three-drug MDT combination used for both PB and MB leprosy in India from April 2025?', 'Rifampicin, dapsone and clofazimine',[
 ('Rifampicin and dapsone only for every new PB case','The revised Indian protocol adds clofazimine for PB.'),('Isoniazid, rifampicin and pyrazinamide','That is not the leprosy MDT combination.'),('Dapsone monotherapy','Monotherapy risks resistance and is obsolete routine care.')],
 'Older two-drug PB teaching must be updated for the current Indian program', '**Both operational groups receive the same three-drug components.**',['Duration differs between PB and MB.','Age and weight determine formulation and dose.'], '**Explain monthly and daily components clearly.**',['Check contraindications and monitor toxicity.','Do not modify the combination without a specialist plan.'],[['R','Rifampicin'],['D','Dapsone'],['C','Clofazimine']],[IN,WH])
q('Which duration pairing fits current WHO/Indian standard MDT for eligible routine leprosy cases?', 'PB: six months; MB: twelve months',[
 ('PB: one week; MB: one month','These courses are inadequate.'),('PB: twelve months; MB: six months','The pairing is reversed.'),('All patients require lifelong dapsone monotherapy','This is not the current standard.')],
 'A shared drug combination does not mean an identical duration', '**PB receives six months and MB twelve months in the standard pathway.**',['Completion windows and interruptions follow national program rules.','Resistance or intolerance requires specialist alternatives.'], '**Monitor disability risk during and after treatment.**',['Reactions can occur after the antimicrobial course.','A completed MDT course does not remove the need for new nerve-symptom assessment.'],[['PB','Six-month course'],['MB','Twelve-month course'],['After completion','Remain alert to reactions and disability']],[WH,IN])
q('Why is serial sensory and voluntary-muscle testing important in leprosy?', 'New nerve impairment can be treatable if recognized early and may occur even without dramatic skin changes',[
 ('The skin-lesion count alone predicts every neurological outcome','It does not.'),('Nerve function never changes once MDT starts','Reactions and nerve injury can occur during or after treatment.'),('A painless nerve cannot be damaged','Silent neuropathy can occur.')],
 'Disability prevention requires functional monitoring, not inspection alone', '**Assess named nerve territories and muscle strength.**',['Compare with a documented baseline.','New weakness or sensory loss needs prompt specialist evaluation.'], '**Protect anesthetic skin and joints.**',['Use appropriate footwear, self-care and rehabilitation.','Assess eye closure and corneal safety when facial involvement is possible.'],[['Baseline','Document sensation and strength'],['Follow-up','Detect new impairment'],['Prevention','Protect insensate tissues']],[UK,RE])
q('A leprosy patient develops clawing of the fourth and fifth fingers with sensory loss in the ulnar distribution. Which structure is primarily implicated?', 'Ulnar peripheral nerve',[
 ('Median nerve alone as the typical ulnar-distribution lesion','The described distribution points to ulnar involvement.'),('An isolated central visual pathway','It does not explain the hand pattern.'),('A pigmentation change without neuropathy','Motor and sensory deficits establish a nerve problem.')],
 'Bedside localization helps detect clinically meaningful nerve injury', '**Ulnar neuropathy can affect intrinsic hand function and sensation.**',['Examine other nerves rather than assuming a single lesion.','A new deficit can indicate active neuritis or reaction.'], '**Assess urgency and protect function.**',['Promptly evaluate recent worsening.','Use splinting, rehabilitation and self-care as appropriate alongside medical treatment.'],[['Motor','Intrinsic-hand weakness/clawing'],['Sensory','Ulnar territory'],['Action','Assess new neuritis and preserve function']],[UK,RE],style='clinical_scenario')
q('Borderline leprosy lesions become acutely red and swollen, with painful neuritis and new weakness. What is most likely?', 'Type 1 reversal reaction',[
 ('Type 2 ENL as the only possible form because fever is present','ENL more characteristically produces crops of tender nodules and systemic features.'),('Relapse is proven by any inflamed old lesion','Immune reactions can occur despite effective antimicrobial treatment.'),('Expected harmless discoloration from clofazimine','That does not explain acute neuritis and weakness.')],
 'Immune inflammation can damage nerves despite bacterial treatment', '**Type 1 reactions commonly affect borderline disease.**',['Existing lesions become inflamed and nerve function can worsen.','New weakness is a disability-threatening sign.'], '**Arrange prompt anti-inflammatory and nerve-function management.**',['Continue MDT unless a separate contraindication requires change.','Do not delay treatment of significant neuritis while debating the skin label.'],[['Type 1','Inflamed existing lesions'],['Major threat','Neuritis and functional loss'],['Response','Prompt specialist treatment']],[UK,RE],style='clinical_scenario')
q('A patient with lepromatous disease develops recurrent crops of tender erythematous nodules with fever, joint pain and possible eye or testicular inflammation. What is most likely?', 'Type 2 reaction, erythema nodosum leprosum',[
 ('An isolated type 1 reaction as the classic nodular systemic syndrome','The described pattern is more typical of ENL.'),('Clofazimine pigmentation without inflammation','Pigment change does not explain the systemic inflammatory nodules.'),('Proof of a new bacterial species from the rash alone','The syndrome can be immunological.')],
 'ENL is a systemic inflammatory reaction associated with higher-burden disease', '**It often occurs toward the BL/LL end of the spectrum.**',['Neuritis, iritis and orchitis can be important.','Relapsing inflammation can require prolonged specialist management.'], '**Assess organ involvement rather than treating the skin alone.**',['Severity determines anti-inflammatory therapy.','Continue appropriate MDT while managing the reaction.'],[['Pattern','Tender nodules in crops'],['Systemic','Fever and possible organ inflammation'],['Context','Usually multibacillary spectrum']],[UK,RE],style='clinical_scenario')
q('What is the usual principle for MDT during a leprosy immune reaction?', 'Continue the indicated antimicrobial course while treating the inflammatory reaction unless a separate drug toxicity requires modification',[
 ('Stop all MDT automatically whenever lesions inflame','A reaction does not inherently indicate drug failure or allergy.'),('Increase antimicrobials indefinitely as the only reaction treatment','Inflammatory injury needs separate management.'),('Assume every reaction proves resistance','Resistance needs appropriate clinical and laboratory assessment.')],
 'Infection control and immune-reaction control are different treatment goals', '**Reactions can occur before, during or after MDT.**',['They do not by themselves establish viable-organism persistence.','Severe drug reactions remain a separate reason to stop an implicated agent.'], '**Use nerve and organ findings to determine anti-inflammatory urgency.**',['New deficits require prompt care.','Do not extend MDT merely because corticosteroids are being used.'],[['MDT','Treats the infection'],['Reaction therapy','Limits inflammatory injury'],['Separate issue','Drug toxicity or proven relapse']],[UK,RE])
q('Which caution is essential if thalidomide is considered for severe/recurrent ENL?', 'Strict pregnancy prevention and specialist control because of profound teratogenicity, with neuropathy and other risks monitored',[
 ('It is safe during pregnancy because leprosy is infectious','It is profoundly teratogenic.'),('It is a routine substitute for MDT in every patient','It treats selected inflammatory reactions, not the bacterial infection.'),('It removes the need to assess nerve involvement','Neuropathy remains important and can also be a drug toxicity.')],
 'An effective anti-inflammatory drug can have exceptional reproductive risk', '**Thalidomide can be useful for selected ENL under controlled access.**',['It is not the routine treatment of type 1 neuritis.','Pregnancy and reproductive safety requirements are strict.'], '**Use a specialist reaction plan.**',['Monitor neurological and thrombotic or other relevant adverse effects.','Organ-threatening neuritis or eye disease may need corticosteroid-based management.'],[['Role','Selected ENL'],['Major risk','Teratogenicity'],['Monitoring','Nerve and other drug toxicity']],[UK,RE])
q('A patient receiving dapsone develops cyanosis with a saturation gap and little improvement in the pulse-oximeter reading with oxygen. Which toxicity should be considered?', 'Methemoglobinemia',[
 ('Orange-fluid discoloration as a harmless explanation for cyanosis','That does not explain abnormal hemoglobin oxygen handling.'),('A normal PaO2 excludes any hemoglobin-related oxygen problem','Dissolved oxygen can be preserved despite methemoglobinemia.'),('Ethambutol optic neuropathy','Ethambutol is not part of standard leprosy MDT and the phenotype differs.')],
 'Oxidant toxicity can impair hemoglobin function', '**Dapsone can cause methemoglobinemia and hemolysis.**',['Co-oximetry helps confirm the diagnosis.','G6PD status and clinical severity affect treatment choices.'], '**Stop/review the implicated drug and treat according to severity.**',['Assess oxygen delivery and hemolysis.','Do not give methylene blue blindly when important contraindications such as G6PD deficiency may apply.'],[['Drug','Dapsone'],['Test','Co-oximetry'],['Safety','Severity and G6PD-aware treatment']],[UK],style='clinical_scenario')
q('Which effect commonly requires counseling during clofazimine treatment?', 'Reddish-brown skin discoloration and dryness, with assessment for significant gastrointestinal toxicity',[
 ('A guaranteed permanent loss of all sensation from pigmentation alone','Pigmentation is not equivalent to new neuropathy.'),('Every color change proves bacterial relapse','Drug pigmentation is a recognized effect.'),('No adverse effects occur because the drug is part of MDT','Tolerability and toxicity still need monitoring.')],
 'Expected appearance changes can affect treatment acceptance', '**Clofazimine can discolor skin and other tissues.**',['Explain the effect before treatment to support informed adherence.','Severe gastrointestinal symptoms need assessment.'], '**Distinguish expected effects from a new inflammatory or neurological problem.**',['Document symptoms rather than dismiss them all as pigment change.','Provide respectful counseling about appearance and stigma.'],[['Expected','Pigmentation and dryness'],['Warning','Significant GI symptoms'],['Care','Counseling and toxicity review']],[UK])
q('A person has been cured of leprosy but has anesthetic feet. Which long-term measure is important?', 'Regular self-inspection, protective footwear and prompt care of injuries to prevent neuropathic ulceration',[
 ('No follow-up because microbial cure reverses every established deficit immediately','Nerve impairment can persist.'),('Walk barefoot to retrain pain sensation','This exposes insensate skin to injury.'),('Treat every ulcer solely by extending MDT without evaluating the wound','Mechanical, vascular and secondary-infection factors require assessment.')],
 'Microbial cure and disability reversal are different outcomes', '**Loss of protective sensation allows unnoticed trauma.**',['Daily inspection can detect injury early.','Pressure redistribution and appropriate footwear reduce risk.'], '**Use rehabilitation and wound care according to function.**',['Assess new nerve deterioration separately.','Support participation and avoid stigmatizing restrictions.'],[['Persistent risk','Anesthetic tissue'],['Prevention','Inspection and protection'],['New problem','Evaluate injury, infection and nerve status']],[UK,RE])
q('What is the appropriate principle for leprosy contact prophylaxis?', 'Screen contacts for disease and eligibility before programmatic single-dose rifampicin prophylaxis where recommended',[
 ('Give rifampicin blindly to every symptomatic contact without assessment','Active leprosy or TB must not be missed.'),('Prophylaxis replaces follow-up and symptom education','Contacts still need awareness and surveillance.'),('The contact must be isolated permanently regardless of disease status','That is unsupported and stigmatizing.')],
 'Contact management combines case detection and selected prevention', '**Single-dose rifampicin PEP has a defined programmatic role.**',['Assess contraindications and relevant disease before use.','Respect confidentiality and obtain appropriate consent in the contact pathway.'], '**Continue education and follow-up.**',['Explain skin and nerve symptoms that should prompt review.','Prevent stigma while enabling early diagnosis.'],[['First','Contact screening'],['Selected prevention','Eligible single-dose rifampicin PEP'],['Ongoing','Education and appropriate follow-up']],[WH,IN])

if __name__=='__main__':finalize('Infectious disease',13,'Leprosy','id-leprosy',rows,16)
